// Production Portfolio Export for ${r.profile.name}
export default function PortfolioWebsite() {
  return (
    <div className="min-h-screen bg-[#0F172A] text-slate-200 font-sans">
      {/* Hero Section */}
      <header className="max-w-6xl mx-auto px-6 py-24 text-center space-y-6">
        <span className="px-4 py-1.5 rounded-full bg-sky-500/10 text-sky-400 text-xs font-bold uppercase tracking-wider border border-sky-500/20">
          ${r.hero.badge}
        </span>
        <h1 className="text-5xl md:text-6xl font-extrabold text-white tracking-tight">
          ${r.hero.headline}
        </h1>
        <p className="text-lg text-slate-400 max-w-2xl mx-auto leading-relaxed">
          ${r.hero.subheadline}
        </p>
        <div className="flex justify-center gap-4 pt-4">
          <a href="#contact" className="px-6 py-3 rounded-xl bg-sky-500 text-slate-950 font-bold hover:bg-sky-400">
            ${r.hero.primaryCta}
          </a>
          <a href="#projects" className="px-6 py-3 rounded-xl border border-slate-700 font-bold hover:bg-slate-800 text-white">
            ${r.hero.secondaryCta}
          </a>
        </div>
      </header>

      {/* Featured Work */}
      <section id="projects" className="max-w-6xl mx-auto px-6 py-16">
        <h2 className="text-3xl font-extrabold text-white mb-8">Featured Projects</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          ${r.projects.projectList.map(x=>`
          <div key="${x.id}" className="p-6 rounded-2xl bg-slate-800/40 border border-slate-700">
            <span className="text-xs text-sky-400 font-bold uppercase">${x.category}</span>
            <h3 className="text-xl font-bold text-white mt-1">${x.title}</h3>
            <p className="text-xs text-slate-400 mt-2">${x.description}</p>
            <div className="mt-4 p-2.5 rounded-lg bg-sky-500/10 text-sky-300 text-xs font-semibold">
              Impact: ${x.impact}
            </div>
          </div>`).join("")}
        </div>
      </section>

      {/* Contact Section */}
      <footer id="contact" className="max-w-4xl mx-auto px-6 py-20 text-center space-y-6">
        <h2 className="text-3xl font-extrabold text-white">Let's Connect</h2>
        <p className="text-slate-400">${r.contact.closingStatement}</p>
        <a href="mailto:${r.contact.directEmail}" className="inline-block px-8 py-3 rounded-xl bg-sky-500 text-slate-950 font-bold">
          Email Me: ${r.contact.directEmail}
        </a>
      </footer>
    </div>
  );
}
